const EMOJI_PART = String.raw`\p{Extended_Pictographic}[\uFE0E\uFE0F]?\p{Emoji_Modifier}?`;
const SINGLE_EMOJI_PATTERN = new RegExp(
	String.raw`^(?:\p{Regional_Indicator}{2}|[0-9#*]\uFE0F?\u20E3|${EMOJI_PART}(?:\u200D${EMOJI_PART})*(?:[\u{E0020}-\u{E007E}]+\u{E007F})?)$`,
	"u",
);

/**
 * Heuristically check if a string contains just a single emoji.
 *
 * Validates structure rather than the runtime's RGI list so newer emoji combinations
 * are accepted. `Extended_Pictographic` also includes reserved future emoji positions.
 * This deliberately accepts some unassigned flags and nonstandard modifier/ZWJ combinations. It
 * does not guarantee that every platform renders one glyph.
 */
export function isSingleEmoji(value: unknown): value is string {
	return (
		typeof value === "string" &&
		value.length > 0 &&
		value.length <= 100 &&
		!/^\p{Emoji_Component}$/u.test(value) &&
		// Compare the full match because $ can also match before a final newline.
		SINGLE_EMOJI_PATTERN.exec(value)?.[0] === value
	);
}
